preConditionHook:
// THE TREND LINE AND THE CHANNEL LINE, the one construction shared by the
// whole lines/channels family (settled in slice B01, recorded in
// author/DECISIONS.md, carried here unchanged): the BULL channel's trend line
// runs through the two most recent CONFIRMED swing LOWS and its channel line
// through the two most recent confirmed swing HIGHS; the BEAR channel is the
// mirror. The two lines are deliberately NOT parallel, which is what lets the
// channel converge or diverge.
//
// The pivot scan is INLINED rather than reaching into SwingHigh.json -- rules
// in this corpus never reference each other -- and mirrors the EL twin's
// SwingLow / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 1 and 2.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR BEYOND the strength OLDER bars, STRICTLY BEYOND the
// strength NEWER bars -- so a flat top yields exactly one pivot, the later of
// the equal bars; bars-ago indexing makes the SMALLER index the NEWER bar, so
// the strict half is the k < j loop. The confirmation lag is exactly strength
// bars, which is what makes the scan lookahead-safe; pivotLookback is EL's
// Length (candidate offsets 0..pivotLookback-1 inclusive) and the
// neighbourhood test reaches strength bars PAST the window, so the deepest
// index the scan touches is pivotLookback - 1 + strength; a window with no
// pivot returns the -1 SENTINEL, guarded below because -1 as a price sits
// under every real price; Occurrence 3+ is UNMEASURED and is never asked for;
// the comparisons carry the 2.22e-12 relational tolerance, hence el_gt /
// el_ge. The low side's tie sense is the mirror of the measured high-side
// rule. No WFSafe_SwingHigh exists, so plain EL governs.
//
// MEASURED, EL_TLValue_Probe.txt (TLVALUE_FINDINGS.md section 4): TLValue is
// the pure two-point line Slope = (P2 - P1) / (B2 - B1);
// value = P1 + (target - B1) * Slope, anchored at the FIRST pair and
// extrapolating freely past both anchors -- which is what lets the line be
// read at an OLDER bar inside the loops below. The bar-number convention is
// the CALLER's; bars-ago is used here, so the OLDER pivot (the LARGER
// bars-ago) is passed as P1/B1, the zero-drift spelling. Bar1 = Bar2 does NOT
// halt, it silently returns 0.0, so both twins guard B1 <> B2 instead of
// relying on that. The slope is hoisted out of the per-target arithmetic here
// where the EL twin recomputes it inside each TLValue call: identical
// doubles, so bit-for-bit the same line.
//
// THE TICK is EL's own MinMove / PriceScale, VERIFIED and per-symbol constant
// for the whole run, written DIVISION-FIRST in both twins so the C++ reads
// token for token against its EasyLanguage (README "N ticks", TICKSIZE_FINDINGS).
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration is a
// redefinition when this rule is placed twice in one strategy. Every one is
// fully assigned each bar before it is read.//
// THIS RULE: the breakout TEST of a broken trend line -- after a bear trend
// line was broken to the UPSIDE, the pullback's lowest low of the last
// pullbackBars bars stays at or above the projected OLD line (within
// toleranceTicks ticks below it) and this bar closes up. Broken resistance
// acting as support; short is the mirror on a broken bull trend line.
//
// Kept apart from TrendLineTouch, which tests an INTACT line from the trend
// side and always uses the newest pivots. This one tests a BROKEN line from
// the far side, so it needs the opposite anchor behaviour.
//
// THE BREAK IS THE CROSSING, not the standing state: the close is beyond the
// line now and the previous bar's close was not beyond the line read at that
// bar. A later break re-freezes the anchors on the newer pair.//
// THE FROZEN ANCHORS, the one place the family's "always redraw from the
// newest pivots" decision does NOT apply: a line that has been broken must
// keep being projected from the pivots it had AT THE BREAK, or the newest
// pivots (which now include bars beyond the break) redraw it into a different
// line. The break bar copies the four anchor values into frozen locals and
// the bars-ago anchors are AGED by one bar at the top of every later bar,
// which is exactly what "the same two points, one bar further back" means and
// leaves the slope unchanged. Locals persist across bars in both twins, so
// this is the same state machine in each.
pivS = (int)swingStrength;
pivW = (int)pivotLookback;
tickSize = ctx.MinMove() / ctx.PriceScale();
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2);
loSlope = 0.0;
hiSlope = 0.0;
if (haveLoLine) loSlope = (loP2 - loP1) / (loB2 - loB1);
if (haveHiLine) hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
loNow = 0.0;
hiNow = 0.0;
if (haveLoLine) loNow = loP1 + (0.0 - loB1) * loSlope;
if (haveHiLine) hiNow = hiP1 + (0.0 - hiB1) * hiSlope;
if (haveFrzUp) {
    frzUpB1 = frzUpB1 + 1.0;
    frzUpB2 = frzUpB2 + 1.0;
}
if (haveFrzDn) {
    frzDnB1 = frzDnB1 + 1.0;
    frzDnB2 = frzDnB2 + 1.0;
}
brokeUp = haveHiLine && el_gt(close[0], hiNow) && el_le(close[1], hiP1 + (1.0 - hiB1) * hiSlope);
brokeDn = haveLoLine && el_lt(close[0], loNow) && el_ge(close[1], loP1 + (1.0 - loB1) * loSlope);
if (brokeUp) {
    frzUpP1 = hiP1;
    frzUpB1 = hiB1;
    frzUpP2 = hiP2;
    frzUpB2 = hiB2;
    haveFrzUp = true;
}
if (brokeDn) {
    frzDnP1 = loP1;
    frzDnB1 = loB1;
    frzDnP2 = loP2;
    frzDnB2 = loB2;
    haveFrzDn = true;
}
frzUpNow = 0.0;
frzDnNow = 0.0;
if (haveFrzUp && (frzUpB1 != frzUpB2)) {
    frzUpSlope = (frzUpP2 - frzUpP1) / (frzUpB2 - frzUpB1);
    frzUpNow = frzUpP1 + (0.0 - frzUpB1) * frzUpSlope;
}
if (haveFrzDn && (frzDnB1 != frzDnB2)) {
    frzDnSlope = (frzDnP2 - frzDnP1) / (frzDnB2 - frzDnB1);
    frzDnNow = frzDnP1 + (0.0 - frzDnB1) * frzDnSlope;
}
// The window extremes mirror EasyLanguage's Extremes(), which Highest() and
// Lowest() call: seeded at bar 0, scanning bars 1..Length-1, strict
// comparison, the window INCLUSIVE of the current bar, and the comparison
// carries the 2.22e-12 tolerance because Extremes is EL source.
loWin = low[0];
hiWin = high[0];
for (int i = 1; i < (int)pullbackBars; ++i) {
    if (el_lt(low[i], loWin)) loWin = low[i];
    if (el_gt(high[i], hiWin)) hiWin = high[i];
}
okUp = haveFrzUp && (frzUpB1 != frzUpB2) && el_ge(loWin, frzUpNow - toleranceTicks * tickSize) && el_gt(close[0], open[0]);
okDn = haveFrzDn && (frzDnB1 != frzDnB2) && el_le(hiWin, frzDnNow + toleranceTicks * tickSize) && el_lt(close[0], open[0]);
